#include <stdio.h>
#include <stdbool.h>

long long countDivisors(long long n) {
    long long count = 0;
    long long p = 1;
    while (p <= n) {
        long long q = n / p;
        if (q * p == n) {
            count = count + 1;
        }
        p = p + 1;
    }
    return count;
}

int main() {
    // Test case 1: n = 1 (smallest positive)
    printf("%lld\n", countDivisors(1));

    // Test case 2: n = 12 (typical case)
    printf("%lld\n", countDivisors(12));

    // Test case 3: n = 17 (prime number)
    printf("%lld\n", countDivisors(17));

    // Test case 4: n = 36 (perfect square)
    printf("%lld\n", countDivisors(36));

    // Test case 5: n = 100 (larger composite)
    printf("%lld\n", countDivisors(100));

    return 0;
}

