import java.util.*;

public class Solution {
    public static long countDivisors(long n) {
        long q = 0L;
        long p = 1L;
        while (p <= n) {
            if (n % p == 0) {
                q = q + 1L;
            }
            p = p + 1L;
        }
        return q;
    }

    public static void main(String[] args) {
        System.out.println(countDivisors(1L));
        System.out.println(countDivisors(2L));
        System.out.println(countDivisors(12L));
        System.out.println(countDivisors(30L));
        System.out.println(countDivisors(100L));
    }
}
